    "deBaiChung": "",
    "question": "Một sợi dây kim loại hình vuông có cạnh bằng $15,7\\text{ cm}$ được đặt trong từ trường đều có cảm ứng từ $0,6\\text{ T}$ hướng vào tờ giấy như hình vẽ. Giả sử hình dạng của nó bây giờ biến thành hình tròn trong thời gian $0,5\\text{ giây}$. Tìm suất điện động cảm ứng trung bình và chiều của dòng điện cảm ứng trong khung trong khoảng thời gian này.\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-TN50-C3-535\"></div>",
    "optA": "Suất điện động: $8,1\\text{ mV}$ — Chiều dòng cảm ứng: Thuận chiều kim đồng hồ.",
    "optB": "Suất điện động: $8,1\\text{ mV}$ — Chiều dòng cảm ứng: Ngược chiều kim đồng hồ.",
    "optC": "Suất điện động: $4,0\\text{ mV}$ — Chiều dòng cảm ứng: Thuận chiều kim đồng hồ.",
    "optD": "Suất điện động: $4,0\\text{ mV}$ — Chiều dòng cảm ứng: Ngược chiều kim đồng hồ.",
    "correct": "B",
    "hinhAnh": "assets/images/staging/q_535_0.jpg",
    "giaiThich": "• Chu vi sợi dây: $C = 4a = 4 \\cdot 0,157 = 0,628\\text{ m}$.<br>• Diện tích hình vuông ban đầu: $S_1 = a^2 = 0,157^2 \\approx 0,02465\\text{ m}^2$.<br>• Bán kính hình tròn sau: $r = \\frac{C}{2\\pi} = \\frac{0,628}{2\\pi} = 0,10\\text{ m} \\implies S_2 = \\pi r^2 \\approx 0,03142\\text{ m}^2$.<br>• Độ lớn suất điện động cảm ứng trung bình:<br>$$|e_c| = B \\cdot \\frac{|S_2 - S_1|}{\\Delta t} = 0,6 \\cdot \\frac{0,03142 - 0,02465}{0,5} \\approx 8,1 \\cdot 10^{-3}\\text{ V} = 8,1\\text{ mV}.$$<br>• Vì diện tích khung tăng nên từ thông xuyên vào tờ giấy tăng; theo định luật Lenz, cảm ứng từ $\\vec{B}_c$ hướng ra ngoài tờ giấy $\\implies$ dòng cảm ứng chạy <b>ngược chiều kim đồng hồ</b>.",
    "ngayThem": "2026-11-18T13:30:00.000Z",
    "baiHoc": "B22. CẢM ỨNG TỪ - LỰC TỪ",
    "chatLuong": "tinh",
    "kyThuat": "Dat",
    "lyDoCachLy": "",
