    "loai": "TN",
    "nhomId": "",
    "deBaiChung": "",
    "question": "Một khung tròn và một khung vuông, được làm từ cùng một loại dây kim loại, được đặt trong một từ trường đều như hình vẽ. Độ dài mỗi cạnh của hình vuông bằng đường kính của hình tròn. Khi mật độ từ thông của từ trường tăng đều, hãy tìm tỷ số giữa dòng điện cảm ứng trong khung tròn và trong khung vuông.\n<div class=\"vlxt-model-slot\" data-model-id=\"MH-TN50-C3-531\"></div>",
    "optA": "$1:1$.",
    "optB": "$1:\\pi$.",
    "optC": "$\\pi:4$.",
    "optD": "$2:\\pi$.",
    "correct": "A",
    "hinhAnh": "assets/images/staging/q_531_0.png",
    "giaiThich": "Gọi $R$ là bán kính khung tròn, cạnh khung vuông là $a = 2R$ và tốc độ biến thiên cảm ứng từ là $k = \\frac{\\Delta B}{\\Delta t}$.<br>• Với khung tròn: diện tích $S_{\\text{tr}} = \\pi R^2$, điện trở $R_{\\text{tr}} = \\rho\\frac{2\\pi R}{s}$ $\\implies I_{\\text{tr}} = \\frac{|e_{\\text{tr}}|}{R_{\\text{tr}}} = \\frac{k \\pi R^2}{\\rho \\frac{2\\pi R}{s}} = \\frac{k R s}{2\\rho}$.<br>• Với khung vuông: diện tích $S_{\\text{v}} = a^2 = 4R^2$, điện trở $R_{\\text{v}} = \\rho\\frac{4a}{s} = \\rho\\frac{8R}{s}$ $\\implies I_{\\text{v}} = \\frac{k \\cdot 4R^2}{\\rho \\frac{8R}{s}} = \\frac{k R s}{2\\rho}$.<br>Vậy tỉ số dòng điện cảm ứng là $\\frac{I_{\\text{tr}}}{I_{\\text{v}}} = 1:1$.",
    "ngayThem": "2026-11-18T13:30:00.000Z",
    "baiHoc": "B25. SUẤT ĐIỆN ĐỘNG CẢM ỨNG - ĐỊNH LUẬT FARADAY",
